use std::env;
use std::fs;
use std::path::PathBuf;

fn main() {
    let args: Vec<String> = env::args().collect();

    if args.len() > 1 && (args[1] == "--version" || args[1] == "-V") {
        println!("tui-journal 0.16.1");
        return;
    }

    if args.len() > 1 && (args[1] == "--help" || args[1] == "-h") {
        print_help();
        return;
    }

    let command = if args.len() >= 2 {
        args[1].clone()
    } else {
        // No command provided - show error
        eprintln!("Error: No such device or address (os error 6)");
        std::process::exit(1);
    };

    match command.as_str() {
        "print-config" | "pc" => {
            print_config();
        }
        "import-journals" | "imj" => {
            if args.len() < 3 {
                eprintln!("Error: Missing path argument");
                std::process::exit(1);
            }
            let path = &args[2];
            import_journals(path);
        }
        "assign-priority" | "ap" => {
            if args.len() < 3 {
                eprintln!("Error: Missing priority argument");
                std::process::exit(1);
            }
            let priority = &args[2];
            assign_priority(priority);
        }
        "theme" | "style" => {
            if args.len() < 3 {
                print_theme_help();
                return;
            }
            let theme_cmd = &args[2];
            match theme_cmd.as_str() {
                "print-path" | "path" => {
                    print_theme_path();
                }
                "print-default" | "default" => {
                    print_default_themes();
                }
                "write-defaults" | "write" => {
                    write_default_themes();
                }
                "help" | "h" => {
                    print_theme_help();
                }
                _ => {
                    eprintln!("Error: Unknown theme command: {}", theme_cmd);
                    std::process::exit(1);
                }
            }
        }
        "help" => {
            print_help();
        }
        _ => {
            eprintln!("Error: Unknown command: {}", command);
            print_help();
            std::process::exit(1);
        }
    }
}
```

